#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import fs from 'node:fs'
import { tokenize, LexError } from './lexer.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const input = readStdin()

  let tokens
  try {
    tokens = tokenize(input)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  const lines = []
  if (mode === 'tokens') {
    for (const t of tokens) {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.value) : t.value
      lines.push(`${t.line}:${t.col} ${t.kind} ${body}`)
    }
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const t of tokens) counts[t.kind]++
    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      lines.push(`${kind} ${counts[kind]}`)
    }
    lines.push(`total ${tokens.length}`)
  }
  const out = lines.length ? lines.join('\n') + '\n' : ''
  process.stdout.write(out)
  process.exit(0)
}

main()

