    const c = lx.peek()
    if (c === '"') {
      lx.advance()
      break
    }
    value += lx.advance()
  }
  return { line: start.line, col: start.col, kind: 'rawstring', value }
}

export function tokenize(input) {
  const lx = new Lexer(input)
  const tokens = []
  while (!lx.atEnd()) {
    const c = lx.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      lx.advance()
      continue
