    if (c === '/' && lx.peek(1) === '/') {
      lx.advance()
      lx.advance()
      while (!lx.atEnd() && lx.peek() !== '\n') lx.advance()
      continue
    }
    if (c === '/' && lx.peek(1) === '*') {
      const start = lx.curPos()
      lx.advance()
      lx.advance()
      let depth = 1
      while (depth > 0) {
        if (lx.atEnd()) throw new LexError(start.line, start.col, 'unterminated block comment')
        if (lx.peek() === '/' && lx.peek(1) === '*') {
          lx.advance()
          lx.advance()
          depth++
          continue
        }
        if (lx.peek() === '*' && lx.peek(1) === '/') {
          lx.advance()
          lx.advance()
          depth--
          continue
        }
        lx.advance()
      }
      continue
    }
    if (c === '"') {
      tokens.push(scanString(lx))
      continue
    }
    if (c === 'r' && lx.peek(1) === '"') {
      tokens.push(scanRawString(lx))
      continue
    }
    if (isIdentStart(c)) {
      tokens.push(scanIdent(lx))
      continue
    }
    if (isDigit10(c)) {
      tokens.push(scanNumber(lx))
      continue
    }
    const p = scanPunct(lx)
    if (p) {
      tokens.push(p)
      continue
    }
    const pos = lx.curPos()
    const ch = lx.advance()
    throw new LexError(pos.line, pos.col, `unexpected character ${ch}`)
  }
