      continue
    }
    if (c === '/' && lx.peek(1) === '/') {
      lx.advance()
      lx.advance()
      while (!lx.atEnd() && lx.peek() !== '\n') lx.advance()
      continue
    }
    if (c === '/' && lx.peek(1) === '*') {
      const start = lx.curPos()
      lx.advance()
      lx.advance()
      let depth = 1
